/**
 * Brandi canvas layer: emit and validate Design Component artboards for
 * Claude's Design canvas, an Artifact type.
 *
 * The division of labour here is deliberate.
 *
 *   Generated by code   the artboards that are SPECIFICATIONS: the palette
 *                       sheet, the type specimen, the component states, the
 *                       token sheet. These have to be exactly right, and a
 *                       machine is better at exactly right than a model is.
 *
 *   Authored by Claude  the artboards that are DESIGN: direction sketches, the
 *                       landing page, the app screen, the poster, the slide.
 *                       Generating those from a template is precisely how a
 *                       brand ends up looking like every other brand.
 *
 * Everything in this file targets the `.dc.html` format the canvas consumes.
 * The format fails silently in several places (a missing image renders as a
 * broken image with no warning; an expression inside a handlebars hole renders
 * as literal text), so `validateArtboard` exists to turn those silent failures
 * into loud ones before anything is published.
 */

const SUPPORT_LINE = '<script src="./support.js"></script>';
const DC_SCRIPT_ATTRS = 'type="text/x-dc" data-dc-script';

/** Frame sizes the canvas and the real world agree on. */
/** The frame the Design canvas accepts, each way, in CSS px: a board outside it cannot be published. */
export const FRAME_LIMIT = Object.freeze({ min: 40, max: 8000 });

export const FRAMES = Object.freeze({
  phone: { w: 390, h: 844, note: 'iPhone logical resolution' },
  phoneLarge: { w: 430, h: 932 },
  tablet: { w: 834, h: 1112 },
  // A product canvas checks 820, which is no device: the width where a tablet
  // layout and a desktop one meet. `tablet` is a device frame and stays one.
  tablet820: { w: 820, h: 1180, note: 'The checked tablet width on a product canvas' },
  desktop: { w: 1440, h: 900 },
  desktopTall: { w: 1440, h: 1600 },
  slide: { w: 1920, h: 1080, note: '16:9. Body type never below 24px at this size' },
  socialSquare: { w: 1080, h: 1080 },
  socialStory: { w: 1080, h: 1920 },
  socialWide: { w: 1200, h: 630, note: 'Open Graph card' },
  // Print, authored at 96 px per inch, which is what the canvas exports at.
  a4: { w: 794, h: 1123, note: 'A4 portrait at 96ppi' },
  a4Landscape: { w: 1123, h: 794 },
  a5: { w: 559, h: 794 },
  letter: { w: 816, h: 1056 },
  businessCard: { w: 336, h: 192, note: '89 x 51 mm at 96ppi' },
  // Physical surfaces. A word-of-mouth business meets its customers on these
  // long before it meets them on a home page, and the proof set said otherwise
  // while the intake said this. Authored at 96ppi like the print frames, at a
  // scale that keeps the file workable rather than at full size.
  signage: { w: 1200, h: 400, note: 'A shopfront band at 1:10. State the real width in mm on the artboard' },
  aFrame: { w: 600, h: 900, note: 'A-frame or sandwich board, 2:3' },
  vehicle: { w: 1400, h: 600, note: 'A van side at 1:10. The door and wheel arch are where artwork dies' },
  garment: { w: 400, h: 400, note: 'An embroidered chest mark, at the size it is actually stitched' },
  sticker: { w: 400, h: 400, note: 'A die-cut sticker or a window decal' },
  sheet: { w: 1200, h: 1600, note: 'A specification sheet. Not a real-world size' },
});

/**
 * Typefaces that make a design look machine-generated on sight. The canvas
 * loads fonts from Google Fonts only, so the replacements named here are all
 * available from that one host.
 */
import { loadContractSync, slopFindings } from './slop.mjs';

// The marker every generated artefact carries in its head. Duplicated as a
// string rather than imported from guardian.mjs, which imports this module.
const GENERATED_MARKER = 'generated from the resolved system';

/**
 * Views of the contract rather than second lists to maintain. The document at
 * references/anti-slop.contract.md is where a face gets banned.
 *
 * The two stay separate because the contract separates them, and folding them
 * together turned "Instrument Serif is a default you should argue for" into
 * "Instrument Serif is forbidden", which is a different and wrong claim.
 * A ban is a p0 and takes a waiver; a default is a p1 and takes a reason.
 */
export const BANNED_FONTS = Object.freeze([...loadContractSync().banned_fonts.literals]);
export const DEFAULT_FONTS = Object.freeze([...(loadContractSync().banned_fonts.soft_literals ?? [])]);

const EMOJI_RE = /\p{Extended_Pictographic}/u;

// ---------------------------------------------------------------------------
// Emitting
// ---------------------------------------------------------------------------

const escapeAttr = (s) =>
  String(s).replace(/&/g, '&amp;').replace(/"/g, '&quot;').replace(/'/g, '&#39;');
const escapeText = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

/**
 * A design system's folder on a canvas. The Design type skips a folder that
 * does not fit this, so a typo here is an install that silently never happens.
 */
export const NAMESPACE_RE = /^[a-z0-9][a-z0-9_-]{0,63}$/;

/**
 * The lines that load an installed design system's copy, straight after the
 * support line: its variables, then its components' styles, then the
 * components. The canvas supplies React, so the bundle never brings its own.
 */
export function systemHeadLines(namespace) {
  if (!NAMESPACE_RE.test(String(namespace))) {
    throw new RangeError(
      `A design system namespace is lower case letters, digits, _ and -, starting with a letter or digit, 64 at most. Got ${JSON.stringify(namespace)}.`,
    );
  }
  return [
    `<link rel="stylesheet" href="ds/${namespace}/tokens.css">`,
    `<link rel="stylesheet" href="ds/${namespace}/components/bundle.css">`,
    `<script src="ds/${namespace}/components/bundle.js"></script>`,
  ];
}

/** Escape a JSON object for a single-quoted `data-props` attribute. */
export function encodeProps(obj) {
  // The runtime reads the attribute with getAttribute, so HTML entities decode
  // first and THEN it is JSON-parsed. Only three characters need escaping;
  // raw UTF-8 passes through untouched.
  return JSON.stringify(obj).replace(/&/g, '&amp;').replace(/'/g, '&#39;');
}

/** Decode a `data-props` attribute back to an object. */
export function decodeProps(attr) {
  return JSON.parse(String(attr).replace(/&#39;/g, "'").replace(/&quot;/g, '"').replace(/&amp;/g, '&'));
}

/**
 * Build one `.dc.html` artboard.
 *
 * @param {object} spec
 * @param {string} spec.name      artboard name, without the extension. PascalCase.
 * @param {string} spec.body      the markup inside <x-dc>. Required.
 * @param {string} [spec.css]     CSS for the <helmet><style> block.
 * @param {string} [spec.fonts]   a Google Fonts stylesheet URL, or several.
 * @param {object} [spec.props]   data-props. Omit for a static artboard.
 * @param {string} [spec.logic]   the body of the Component class. Omit for static.
 * @param {{width:number,height:number}} [spec.preview]
 * @param {string} [spec.systemNote]  the mini-system comment. Strongly encouraged.
 * @param {string} [spec.title]   the screen's name in a few words, for <title>.
 * @param {string} [spec.lang]    the copy's language, for <html lang>.
 * @param {string} [spec.system]  an installed design system's namespace: its head lines follow support.js.
 */
export function artboard(spec) {
  const { name, body, css = '', fonts, props, logic, preview, systemNote, title, lang, system } = spec;
  if (!name || !/^[A-Z][A-Za-z0-9]*$/.test(name)) {
    throw new TypeError(`artboard name must be PascalCase with no extension, got ${JSON.stringify(name)}`);
  }
  if (!body || !body.trim()) throw new TypeError(`artboard ${name} has no body`);
  if (lang !== undefined && !/^[A-Za-z]{2,3}(-[A-Za-z0-9]{2,8})*$/.test(lang)) {
    throw new RangeError(`artboard ${name}: lang must be a language tag such as en or en-AU, got ${JSON.stringify(lang)}`);
  }
  const headLines = system !== undefined ? systemHeadLines(system) : [];

  const fontLinks = (Array.isArray(fonts) ? fonts : fonts ? [fonts] : [])
    .map((href) => {
      if (!/^https:\/\/fonts\.googleapis\.com\//.test(href)) {
        throw new RangeError(
          `The canvas can only load fonts from fonts.googleapis.com. Got ${href}. ` +
            'Anything else is uploaded to the canvas as an asset and named in an @font-face rule by its /_blob/ url.',
        );
      }
      return `    <link rel="stylesheet" href="${escapeAttr(href)}">`;
    })
    .join('\n');

  // $preview is a component-level size hint that lives in data-props, so a
  // preview with no other props still needs the attribute. Missing this meant
  // the hint was silently dropped.
  const propsPayload = { ...(props ?? {}), ...(preview ? { $preview: preview } : {}) };
  const propsAttr = Object.keys(propsPayload).length ? ` data-props='${encodeProps(propsPayload)}'` : '';

  const parts = [];
  parts.push('<!doctype html>');
  parts.push(lang ? `<html lang="${lang}">` : '<html>');
  parts.push('<head>');
  parts.push('  <meta charset="utf-8">');
  if (title) parts.push(`  <title>${escapeText(title)}</title>`);
  parts.push(`  ${SUPPORT_LINE}`);
  for (const line of headLines) parts.push(`  ${line}`);
  parts.push('</head>');
  parts.push('<body>');
  if (systemNote) {
    parts.push('<!--');
    for (const line of String(systemNote).trim().split('\n')) {
      parts.push(`  ${line.replace(/--/g, '- -')}`);
    }
    parts.push('-->');
  }
  parts.push('<x-dc>');
  parts.push('<helmet>');
  if (fontLinks) parts.push(fontLinks);
  parts.push('  <style>');
  parts.push(indent(baseCss() + '\n' + css, 4));
  parts.push('  </style>');
  parts.push('</helmet>');
  parts.push(body.trim());
  parts.push('</x-dc>');
  // Always present, static artboards included: the Design canvas expects the
  // block on every artboard and fails silently without it.
  parts.push(`<script ${DC_SCRIPT_ATTRS}${propsAttr}>`);
  parts.push('class Component extends DCLogic {');
  parts.push(indent(logic ?? '', 2));
  parts.push('}');
  parts.push('</script>');
  parts.push('</body>');
  parts.push('</html>');
  parts.push('');
  return parts.join('\n');
}

function indent(text, n) {
  const pad = ' '.repeat(n);
  return String(text)
    .split('\n')
    .map((l) => (l.trim() ? pad + l : l))
    .join('\n');
}

/**
 * The floor every artboard sits on. Deliberately tiny: it resets the things
 * that bite (default margin, browser-blue links, images overflowing their
 * frame) and decides nothing else.
 *
 * It sits in the base layer. Unlayered CSS beats every layer whatever its
 * specificity, so an unlayered `a { color: inherit }` beat a mounted
 * component's Tailwind utilities: a primary Button given an href drew dark
 * text on its fill. Layered, a board's own CSS still wins and so do utilities.
 */
function baseCss() {
  return `@layer base {
  * { box-sizing: border-box; }
  body { margin: 0; }
  img, svg { max-width: 100%; }
  a { color: inherit; text-decoration-thickness: 0.06em; text-underline-offset: 0.18em; }
  a:hover { text-decoration-thickness: 0.12em; }
}`;
}

// ---------------------------------------------------------------------------
// canvas.json
// ---------------------------------------------------------------------------

/**
 * Lay artboards out in rows and emit a canvas.json manifest.
 *
 * Gaps are not cosmetic: the canvas draws a name strip and tweak chips above
 * each frame, so frames closer than 80px in a row (or 120px between rows)
 * collide with each other's chrome.
 */
export function canvasManifest(entries, {
  columns = 3,
  gapX = 120,
  gapY = 200,
  originX = 0,
  originY = 0,
  pages,
  annotations,
  launch,
  designSystems,
} = {}) {
  if (!entries.length) throw new TypeError('a canvas needs at least one artboard');

  const seen = new Set();
  for (const e of entries) {
    if (!e || typeof e.file !== 'string') throw new TypeError('every artboard entry needs a file name');
    const stem = e.file.replace(/\.dc\.html$/, '').toLowerCase();
    if (seen.has(stem)) throw new RangeError(`duplicate artboard name: ${e.file}`);
    seen.add(stem);
    if (!/\.dc\.html$/.test(e.file)) throw new RangeError(`artboard files must end in .dc.html, got ${e.file}`);
    // One missing width used to make x NaN for every artboard after it, which
    // JSON writes as null and the overlap check cannot see, so a broken layout
    // shipped silently to the seeder.
    for (const [k, required] of [['w', true], ['h', true], ['x', false], ['y', false]]) {
      const v = e[k];
      if (v === undefined && !required) continue;
      if (typeof v !== 'number' || !Number.isFinite(v)) {
        throw new TypeError(`${e.file}: ${k} must be a finite number, got ${JSON.stringify(v)}`);
      }
      if ((k === 'w' || k === 'h') && v <= 0) {
        throw new RangeError(`${e.file}: ${k} must be positive, got ${v}`);
      }
    }
  }

  // Lay out each page independently.
  //
  // A canvas shows one page at a time, so a single cursor running across every
  // artboard is wrong: page A takes positions 1 and 2, page B takes 3 and 4,
  // and each page then renders with the other's slots left as holes. The result
  // is a canvas that looks half-empty and scattered, which is exactly what it
  // was. Each page gets its own cursor, starting at the origin.
  const placed = [];
  const pageOf = (e) => e.page ?? '\u0000default';
  const order = [...new Set(entries.map(pageOf))];

  // `columns` is a number, or an object keyed by page id (with an optional
  // `default`) when pages want different widths: a specification page of nine
  // tall sheets reads at fit zoom five across, a design page of two does not.
  const columnsFor = (pageId) => (typeof columns === 'object' && columns !== null
    ? (columns[pageId] ?? columns.default ?? 3)
    : columns);
  for (const pageId of order) {
    let x = originX;
    let y = originY;
    let rowHeight = 0;
    let col = 0;
    const cols = columnsFor(pageId);
    for (const e of entries.filter((entry) => pageOf(entry) === pageId)) {
      // An explicitly positioned artboard keeps its place and does not move the
      // cursor: it was put there on purpose.
      const explicit = Number.isFinite(e.x) && Number.isFinite(e.y);
      if (!explicit && col >= cols) {
        x = originX;
        y += rowHeight + gapY;
        rowHeight = 0;
        col = 0;
      }
      placed.push({
        file: e.file,
        x: Math.round(explicit ? e.x : x),
        y: Math.round(explicit ? e.y : y),
        w: e.w,
        h: e.h,
        ...(e.title ? { title: e.title } : {}),
        ...(e.expand ? { expand: e.expand } : {}),
        ...(e.print ? { print: e.print } : {}),
        ...(e.page ? { page: e.page } : {}),
        ...(typeof e.is_interactive === 'boolean' ? { is_interactive: e.is_interactive } : {}),
      });
      if (!explicit) {
        x += e.w + gapX;
        rowHeight = Math.max(rowHeight, e.h);
        col++;
      }
    }
  }

  const manifest = { artboards: placed };
  if (annotations?.length) {
    const ids = new Set();
    for (const a of annotations) {
      if (!/^[A-Za-z0-9_-]{1,40}$/.test(a.id)) throw new RangeError(`bad annotation id: ${a.id}`);
      if (ids.has(a.id)) throw new RangeError(`duplicate annotation id: ${a.id}`);
      ids.add(a.id);
      if (typeof a.text !== 'string') throw new TypeError(`annotation ${a.id} text must be one plain string`);
      if (a.kind !== undefined && !/^[a-z][a-z0-9]{0,23}$/.test(a.kind)) {
        throw new RangeError(`annotation ${a.id} kind must be a plain word such as title1, got ${JSON.stringify(a.kind)}`);
      }
      // A sticky is drawn at its width, so it needs one. A title is one line,
      // sized by maxW, and a width is optional. An undefined width used to pass
      // here and reach the index as null.
      if (a.kind === undefined || a.w !== undefined) {
        if (!(a.w >= 120 && a.w <= 2000)) throw new RangeError(`annotation ${a.id} width must be 120-2000`);
      }
      for (const k of ['maxW', 'maxH']) {
        if (a[k] !== undefined && !(Number.isFinite(a[k]) && a[k] > 0)) {
          throw new RangeError(`annotation ${a.id} ${k} must be a positive number, got ${JSON.stringify(a[k])}`);
        }
      }
    }
    manifest.annotations = annotations.map((a) => ({
      id: a.id, x: Math.round(a.x), y: Math.round(a.y),
      ...(a.w !== undefined ? { w: Math.round(a.w) } : {}),
      text: a.text,
      ...(a.kind ? { kind: a.kind } : {}),
      ...(a.maxW !== undefined ? { maxW: Math.round(a.maxW) } : {}),
      ...(a.maxH !== undefined ? { maxH: Math.round(a.maxH) } : {}),
      ...(a.page ? { page: a.page } : {}),
    }));
  }
  if (designSystems?.length) manifest.designSystems = designSystems.map(checkSystemRecord);
  if (pages?.length) {
    if (pages.length > 40) throw new RangeError('a canvas may have at most 40 pages');
    const pageIds = new Set(pages.map((p) => p.id));
    for (const p of pages) {
      if (!p.name) throw new TypeError(`page ${p.id} needs a name`);
      if (!/^[A-Za-z0-9_-]{1,40}$/.test(p.id)) throw new RangeError(`bad page id: ${p.id}`);
    }
    for (const a of placed) {
      if (a.page && !pageIds.has(a.page)) throw new RangeError(`${a.file} is on unlisted page ${a.page}`);
    }
    manifest.pages = pages.map((p) => ({ id: p.id, name: p.name }));
  }
  if (launch) {
    if (launch.view === 'focused') {
      if (!placed.some((a) => a.file === launch.file)) {
        throw new RangeError(`launch targets ${launch.file}, which is not on the canvas`);
      }
      manifest.launch = { view: 'focused', file: launch.file };
    } else if (launch.view === 'canvas') {
      if (launch.page && !manifest.pages?.some((p) => p.id === launch.page)) {
        throw new RangeError(`launch targets unlisted page ${launch.page}`);
      }
      manifest.launch = { view: 'canvas', ...(launch.page ? { page: launch.page } : {}) };
    } else {
      throw new RangeError(`launch.view must be "canvas" or "focused", got ${launch.view}`);
    }
  }
  return manifest;
}

// ---------------------------------------------------------------------------
// The Design canvas
// ---------------------------------------------------------------------------

/**
 * One artboard as the Design canvas takes it.
 *
 * The canvas wants the logic block on every artboard, typed `text/x-dc`, and
 * renders wrongly without saying so when either is missing. Artboards written
 * before that, and artboards authored by hand, often have neither, so the fix is
 * made once here, on the way out, rather than in every author's head.
 */
export function forDesignCanvas(source) {
  let out = source.replace(/<script\b([^>]*\bdata-dc-script\b[^>]*)>/g, (tag, attrs) =>
    (/\btype\s*=/.test(attrs) ? tag : `<script type="text/x-dc"${attrs}>`));
  if (!/<script\b[^>]*\bdata-dc-script\b/.test(out)) {
    const block = `<script ${DC_SCRIPT_ATTRS}>\nclass Component extends DCLogic {\n}\n</script>\n`;
    out = /<\/body>/i.test(out) ? out.replace(/<\/body>/i, `${block}</body>`) : `${out}\n${block}`;
  }
  return out;
}

/**
 * A design system record as Brandi's canvas.json carries it. `artifact` is the
 * system's address cut after its id, on the hosts the Design type accepts;
 * `files` is Brandi's own extension, the files to copy on this publish, and
 * never reaches the canvas's index. A record without `artifact` only declares
 * a namespace, so a board's head lines validate before the system is installed.
 */
const ARTIFACT_RE = /^https:\/\/(preview\.)?claude\.(ai|com)\/(code\/)?artifact\/[A-Za-z0-9_-]+$/;
const SAFE_PATH_RE = /^(?!\/)(?!.*(^|\/)\.\.?(\/|$))[A-Za-z0-9_.\/-]+$/;

export function checkSystemRecord(rec) {
  if (!rec || typeof rec !== 'object') throw new TypeError('a design system record must be an object');
  if (!NAMESPACE_RE.test(String(rec.namespace))) {
    throw new RangeError(`design system namespace ${JSON.stringify(rec.namespace)} must be lower case letters, digits, _ and -, 64 at most`);
  }
  if (rec.artifact !== undefined && !ARTIFACT_RE.test(String(rec.artifact))) {
    throw new RangeError(
      `design system ${rec.namespace}: artifact must be the system's address cut after its id, on claude.ai or claude.com, got ${JSON.stringify(rec.artifact)}`,
    );
  }
  if (rec.files !== undefined) {
    if (!rec.artifact) throw new RangeError(`design system ${rec.namespace}: files to copy need the system's artifact address`);
    if (!Array.isArray(rec.files) || !rec.files.every((f) => typeof f === 'string' && SAFE_PATH_RE.test(f))) {
      throw new RangeError(`design system ${rec.namespace}: files must be relative paths inside the system, with no .. and no leading /`);
    }
  }
  return { ...rec };
}

const artifactId = (url) => String(url).split('/').pop();

// The keys Brandi writes on its own boards. Anything else on an entry (the
// editor's `frameless`, `guides`, `radius`, `paper`) belongs to the canvas.
const BOARD_KEYS = ['x', 'y', 'w', 'h', 'title', 'page', 'expand', 'print', 'is_interactive'];

/**
 * Whether a board's controls need to take clicks on the canvas: it mounts a component (an x-import, or
 * h(Ns.Component) in its logic) or wires a handler to a hole (onClick="{{ item.pick }}"). A DCLogic class on its
 * own says nothing: every board carries one, static ones included, because the canvas expects the block on all of
 * them. Read from the source text; a comment that names an x-import mounts nothing.
 */
export function boardIsInteractive(source) {
  const text = String(source ?? '').replace(/<!--[\s\S]*?-->/g, '');
  const scripts = [...text.matchAll(/<script\b[^>]*>([\s\S]*?)<\/script>/gi)].map((m) => m[1]).join('\n');
  const markup = text.replace(/<(script|style)\b[^>]*>[\s\S]*?<\/\1>/gi, '');
  return /<x-import\b/i.test(markup) || /\son[\w-]*\s*=\s*(["'])\s*\{\{[^}]*\}\}\s*\1/i.test(markup) || /\bh\(\s*[A-Za-z_$][\w$]*\.[A-Z]/.test(scripts);
}

/**
 * Brandi's canvas.json, written as the Design canvas's own index (version 3).
 *
 * Brandi keeps its own manifest shape because the validator, the preview and
 * the logo boards all read it. This is the translation at the edge: `boards`
 * keyed by file, `order` back to front with Main first, annotations as notes.
 *
 * With `base`, the index merges into an index that exists: the live one read
 * from the canvas right before the write, or the last local publish. Only
 * Brandi's own keys change. Boards a person added on the canvas, their notes,
 * keys the editor set and the installed systems all survive, because a publish
 * that rebuilt the index from scratch dropped every one of them. `removed`
 * names boards an earlier publish from this folder sent and this one does not. With `previous`, the index that
 * publish wrote, a board or note a person moved on the canvas keeps their position, shifted only by what the
 * layout itself moved since: a board that grew still pushes the ones below it down, and nothing jumps back.
 *
 * `sources` maps each board's file to its text. A board that mounts a component or wires a handler is marked
 * is_interactive, so its controls take clicks on the canvas: nothing set it by hand, and a published board's
 * mounted controls sat dead. An entry that says is_interactive: false keeps its word.
 */
export function designIndex({ manifest, title, createdOnFiles = null, now = new Date(), base = null, previous = null, removed = [], sources = null }) {
  if (!title) throw new TypeError('a canvas needs a title');
  if (!manifest?.artboards?.length) throw new TypeError('a canvas needs at least one artboard');
  const prev = base && typeof base === 'object' && !Array.isArray(base) ? structuredClone(base) : {};
  const gone = new Set(removed);

  // Where a person put a thing, if they moved it since the last publish: theirs plus the layout's own shift.
  const place = (now, was, there) => (was && there && (there.x !== was.x || there.y !== was.y)
    ? { x: there.x + (now.x - was.x), y: there.y + (now.y - was.y) }
    : { x: now.x, y: now.y });
  const boards = {};
  for (const [file, entry] of Object.entries(prev.boards ?? {})) if (!gone.has(file)) boards[file] = entry;
  for (const a of manifest.artboards) {
    const kept = { ...(boards[a.file] ?? {}) };
    const at = place(a, previous?.boards?.[a.file], prev.boards?.[a.file]);
    for (const k of BOARD_KEYS) delete kept[k];
    boards[a.file] = {
      ...kept,
      x: at.x, y: at.y, w: a.w, h: a.h,
      ...(a.title ? { title: a.title } : {}),
      ...(a.page ? { page: a.page } : {}),
      ...(a.expand ? { expand: a.expand } : {}),
      ...(a.print ? { print: a.print } : {}),
      ...(a.is_interactive === true || (a.is_interactive !== false && boardIsInteractive(sources?.get(a.file))) ? { is_interactive: true } : {}),
    };
  }

  const files = manifest.artboards.map((a) => a.file);
  const order = (Array.isArray(prev.order) ? prev.order : []).filter((f) => boards[f]);
  for (const f of [...files, ...Object.keys(boards)]) if (!order.includes(f)) order.push(f);
  // The entry artboard leads, wherever an earlier order put it.
  if (order.includes('Main.dc.html')) order.unshift(...order.splice(order.indexOf('Main.dc.html'), 1));

  const notes = { ...(prev.notes ?? {}) };
  for (const n of manifest.annotations ?? []) {
    const at = place(n, previous?.notes?.[n.id], prev.notes?.[n.id]);
    notes[n.id] = {
      ...(notes[n.id] ?? {}),
      x: at.x, y: at.y, text: n.text,
      ...(n.w !== undefined ? { w: n.w } : {}),
      ...(n.kind ? { kind: n.kind } : {}),
      ...(n.maxW !== undefined ? { maxW: n.maxW } : {}),
      ...(n.maxH !== undefined ? { maxH: n.maxH } : {}),
      ...(n.page ? { page: n.page } : {}),
    };
  }

  const pages = [...(prev.pages ?? [])];
  for (const p of manifest.pages ?? []) {
    const i = pages.findIndex((q) => q.id === p.id);
    if (i >= 0) pages[i] = { ...pages[i], ...p };
    else pages.push(p);
  }

  // A record goes in place of the first one holding its namespace, a later
  // duplicate is taken out, and every other record stays exactly as it is.
  const systems = [...(prev.designSystems ?? [])];
  for (const rec of manifest.designSystems ?? []) {
    if (!rec.artifact) continue;
    const { files: copying, ...record } = rec;
    if (copying?.length || !record.copiedAt) record.copiedAt = now.toISOString();
    if (record.version === undefined) record.version = null;
    const i = systems.findIndex((s) => s.namespace === record.namespace);
    if (i >= 0) {
      if (systems[i].artifact && artifactId(systems[i].artifact) !== artifactId(record.artifact)) {
        throw new RangeError(
          `The namespace ${record.namespace} is already held by another design system (${systems[i].artifact}). Another namespace, or which system stays, is the person's call.`,
        );
      }
      systems[i] = record;
      for (let j = systems.length - 1; j > i; j--) if (systems[j].namespace === record.namespace) systems.splice(j, 1);
    } else {
      systems.push(record);
    }
  }
  if (systems.length > 4) throw new RangeError(`A canvas holds four design systems at most; this index would hold ${systems.length}.`);

  return {
    ...prev,
    v: 3,
    createdOnFiles: prev.createdOnFiles ?? createdOnFiles ?? { v: 1, at: now.toISOString() },
    // A canvas keeps the title it has: the person may have renamed it.
    title: prev.title ?? title,
    launch: manifest.launch ?? prev.launch ?? { view: 'canvas' },
    pages,
    boards,
    order,
    notes,
    designSystems: systems,
  };
}

/**
 * Frames that do not overlap but sit too close for the canvas chrome.
 *
 * The recipe promises this is checked, so it is checked. A name strip and a row
 * of tweak chips sit above every frame; below about 120px of vertical gap they
 * start crowding the frame above, and side by side under 80px the titles run
 * together. Neither clips content, so these are warnings rather than errors.
 */
export function findCrowding(manifest, { minX = 80, minY = 120 } = {}) {
  const tight = [];
  const boards = manifest.artboards;
  for (let i = 0; i < boards.length; i++) {
    for (let j = i + 1; j < boards.length; j++) {
      const a = boards[i];
      const b = boards[j];
      if ((a.page ?? null) !== (b.page ?? null)) continue;
      const overlapY = a.y < b.y + b.h && b.y < a.y + a.h;
      const overlapX = a.x < b.x + b.w && b.x < a.x + a.w;
      if (overlapY) {
        const gapX = a.x < b.x ? b.x - (a.x + a.w) : a.x - (b.x + b.w);
        if (gapX >= 0 && gapX < minX) tight.push({ a: a.file, b: b.file, axis: 'x', gap: Math.round(gapX), min: minX });
      }
      if (overlapX) {
        const gapY = a.y < b.y ? b.y - (a.y + a.h) : a.y - (b.y + b.h);
        if (gapY >= 0 && gapY < minY) tight.push({ a: a.file, b: b.file, axis: 'y', gap: Math.round(gapY), min: minY });
      }
    }
  }
  return tight;
}

/** Do any two frames on the same page overlap, chrome included? */
export function findOverlaps(manifest, { chromeTop = 56 } = {}) {
  const clashes = [];
  const boards = manifest.artboards;
  for (let i = 0; i < boards.length; i++) {
    for (let j = i + 1; j < boards.length; j++) {
      const a = boards[i];
      const b = boards[j];
      if ((a.page ?? null) !== (b.page ?? null)) continue;
      const ax1 = a.x; const ax2 = a.x + a.w;
      const ay1 = a.y - chromeTop; const ay2 = a.y + a.h;
      const bx1 = b.x; const bx2 = b.x + b.w;
      const by1 = b.y - chromeTop; const by2 = b.y + b.h;
      if (ax1 < bx2 && bx1 < ax2 && ay1 < by2 && by1 < ay2) {
        clashes.push({ a: a.file, b: b.file });
      }
    }
  }
  return clashes;
}

// ---------------------------------------------------------------------------
// Validation
// ---------------------------------------------------------------------------

/**
 * Check an artboard against the parts of the format that fail silently, and
 * against the house rules that keep output from looking machine-made.
 *
 * Returns `{ok, errors, warnings}`. Errors mean the artboard will not render
 * correctly. Warnings mean it will render, and look generic.
 */
export function validateArtboard(source, { name = 'artboard', allowFonts = true, brandFonts = [], systems = [], stylesheets } = {}) {
  const errors = [];
  const warnings = [];
  const err = (m, fix) => errors.push({ message: m, fix });
  const warn = (m, fix) => warnings.push({ message: m, fix });

  // A file of an installed design system's copy is the canvas's own file, so
  // the rule against outside scripts and stylesheets does not touch it. The
  // namespace has to be one the index records, or the file is not there.
  const installed = new Set(systems);
  const systemFile = (ref) => {
    const m = /^(?:\.\/|(?:\.\.\/)+)?ds\/([^/]+)\/(.+)$/.exec(ref ?? '');
    if (!m) return null;
    const safe = SAFE_PATH_RE.test(m[2]) && !/[\\%:;]/.test(ref);
    return { ns: m[1], ok: safe && installed.has(m[1]), safe };
  };
  const systemError = (kind, ref, sys) => err(
    sys.safe
      ? `${kind} ${ref}, but canvas.json records no design system with the namespace ${sys.ns}.`
      : `${kind} ${ref}, a path the canvas will not serve.`,
    sys.safe
      ? 'Record the system in designSystems in canvas.json and install its files under ds/<namespace>/, or fix the namespace.'
      : 'Name a file inside the system with letters, digits, _ . - and /, and no .. folder.',
  );

  // --- Structure ---------------------------------------------------------
  if (!source.includes(SUPPORT_LINE)) {
    err(
      'The support.js head line is missing or altered.',
      `Include exactly: ${SUPPORT_LINE}. The editor swaps it for the inline runtime at render time.`,
    );
  }
  if (!/<x-dc>/.test(source) || !/<\/x-dc>/.test(source)) {
    err('No <x-dc> root element.', 'Wrap the artboard content in <x-dc>...</x-dc>.');
  }
  const scriptTags = [...source.matchAll(/<script\b([^>]*)>/g)];
  for (const [, attrs] of scriptTags) {
    if (/src\s*=/.test(attrs) && !/src\s*=\s*"\.\/support\.js"/.test(attrs)) {
      const src = /src\s*=\s*"([^"]*)"/.exec(attrs)?.[1];
      const sys = systemFile(src);
      if (sys?.ok) continue;
      if (sys) { systemError('A script loads', src, sys); continue; }
      err(
        `An external script is loaded: ${attrs.trim()}`,
        'The canvas has no network egress. Inline the code instead.',
      );
    }
  }

  // --- The logic block ---------------------------------------------------
  // Match on the ATTRIBUTE, not on its position: `<script data-props='...'
  // data-dc-script>` is legal HTML and defeated the old position-anchored
  // regex, so a malformed block validated clean by being written backwards.
  // Every block is checked, not just the first: a second, empty one errors at
  // runtime and used to pass here.
  const dcScripts = [...source.matchAll(/<script\b([^>]*\bdata-dc-script\b[^>]*)>([\s\S]*?)<\/script>/g)];
  if (dcScripts.length > 1) {
    warn(
      `${dcScripts.length} logic blocks. The runtime uses one.`,
      'Merge them into a single `class Component extends DCLogic`.',
    );
  }
  for (const dcScript of dcScripts) {
    const [, attrs, code] = dcScript;
    if (!code.trim()) {
      err('An empty <script data-dc-script> block will error.', 'A static artboard declares `class Component extends DCLogic {}` and nothing else.');
    } else if (!/class\s+Component\s+extends\s+DCLogic/.test(code)) {
      err('The logic block must declare `class Component extends DCLogic`.', null);
    }
    // Statements, not words: example data such as "The export to [the bank] failed" is not a module.
    const statements = code
      .replace(/"(?:[^"\\\n]|\\.)*"|'(?:[^'\\\n]|\\.)*'|`(?:[^`\\]|\\.)*`/g, (q) => q[0] + q[0])
      .replace(/\/\*[\s\S]*?\*\/|\/\/[^\n]*/g, '');
    if (/(^|[\n;])\s*import\s*[\w{*'"]|(^|[\n;{}])\s*export\s/.test(statements)) {
      err('The logic block is classic script, not a module. import and export will fail.', null);
    }
    if (/\brender\s*\(/.test(code) && !/renderVals/.test(code)) {
      warn('A render() method is not part of the contract.', 'Return template inputs from renderVals() instead.');
    }
    const propsAttr = /data-props\s*=\s*(['"])([\s\S]*?)\1/.exec(attrs);
    if (propsAttr) {
      if (propsAttr[1] !== "'") {
        err('data-props must be single-quoted.', "Write data-props='{...}' so JSON double quotes survive.");
      }
      try {
        const preview = decodeProps(propsAttr[2])?.$preview;
        for (const [side, px] of [['width', preview?.width], ['height', preview?.height]]) {
          if (typeof px === 'number' && (px < FRAME_LIMIT.min || px > FRAME_LIMIT.max)) {
            err(`The ${side} in $preview is ${px}px; the Design canvas takes a frame of ${FRAME_LIMIT.min} to ${FRAME_LIMIT.max}px each way, so ${name} cannot be published.`, 'Split the board into parts that each fit, or make it smaller.');
          }
        }
      } catch (e) {
        err(`data-props is not valid JSON after entity decoding: ${e.message}`, null);
      }
    }
  }

  // --- Handlebars holes --------------------------------------------------
  for (const m of source.matchAll(/\{\{([^}]*)\}\}/g)) {
    const inner = m[1].trim();
    const isDotted = /^\$?[A-Za-z_][\w$]*(\.[A-Za-z_$][\w$]*|\.\d+)*$/.test(inner);
    const isLiteral = /^(true|false|null|-?\d+(\.\d+)?|'[^']*'|"[^"]*")$/.test(inner);
    if (!isDotted && !isLiteral) {
      err(
        `{{${inner}}} is not a dotted lookup. Holes cannot contain expressions, and this will render as literal text.`,
        'Compute the value in renderVals() and bind the result.',
      );
    }
  }
  // Ternaries written around a hole are the classic version of the same bug.
  // The shape has to be a WHOLE ternary inside an ATTRIBUTE value: a question
  // mark after a hole is ordinary copy ("Ready to go, {{name}}?") and used to
  // be reported as an error, which blocked publishing on a legitimate headline.
  if (/=\s*"[^"]*\{\{[^}]+\}\}[^"]*\?[^"]*:[^"]*"/.test(source)
    || /=\s*'[^']*\{\{[^}]+\}\}[^']*\?[^']*:[^']*'/.test(source)) {
    err(
      'A ternary sits outside a handlebars hole in an attribute value, so it renders as literal text and the attribute is dropped.',
      'Precompute the branch in renderVals() and bind the result.',
    );
  }

  // --- Images ------------------------------------------------------------
  for (const m of source.matchAll(/<img\b[^>]*>/g)) {
    const tag = m[0];
    const src = /src\s*=\s*("([^"]*)"|'([^']*)'|([^\s>]+))/.exec(tag);
    if (!src) {
      err(`An <img> has no src: ${tag.slice(0, 80)}`, null);
      continue;
    }
    if (!src[2]) {
      err(
        `An image src must be double-quoted for the canvas to substitute it: ${tag.slice(0, 80)}`,
        'Write <img src="logo.png">, not single quotes and not unquoted.',
      );
    }
    const value = src[2] ?? src[3] ?? src[4];
    if (/^data:/.test(value)) {
      err(
        'An image src is a data: URI, which the Design canvas does not take.',
        'Save the image as a file in the canvas folder and name it by filename: `brandi canvas` publishes it beside the artboard.',
      );
    }
    if (/^https?:\/\//.test(value)) {
      err(`An image is loaded from ${value}, but the canvas has no network egress.`, 'Save it as a file in the canvas folder and name it by filename.');
    }
    if (!/alt\s*=/.test(tag)) {
      warn(`An image has no alt attribute: ${tag.slice(0, 60)}`, 'Add alt="" for decoration, or a real description.');
    }
  }

  // --- Anything else that tries to reach the network ----------------------
  // The canvas has no egress. Each of these renders as a silent nothing, which
  // is precisely the class of failure this validator exists to make loud.
  // Google Fonts is the one carve-out in the CSP, and it is reachable through
  // @import as well as <link>, so the generic check has to know that or it
  // rejects the only remote resource that actually works.
  const FONT_HOSTS = /^https:\/\/fonts\.(googleapis|gstatic)\.com\//;
  for (const m of source.matchAll(/url\(\s*['"]?(https?:\/\/[^)'"\s]+)/gi)) {
    if (FONT_HOSTS.test(m[1])) continue;
    err(
      `CSS loads ${m[1]}, and the canvas has no network egress.`,
      'Inline it: an image as a file in the canvas folder named by filename, everything else as literal CSS.',
    );
  }
  for (const m of source.matchAll(/@import\s+(?:url\(\s*)?['"]?(https?:\/\/[^)'"\s;]+)/gi)) {
    if (FONT_HOSTS.test(m[1])) continue;
    err(`An @import reaches ${m[1]}, which the canvas blocks.`, 'Google Fonts is the only permitted host.');
  }
  for (const m of source.matchAll(/<(iframe|video|audio|object|embed|source|track)\b([^>]*)>/gi)) {
    const url = /(?:src|data)\s*=\s*"([^"]*)"/.exec(m[2])?.[1] ?? '';
    if (/^https?:\/\//.test(url)) {
      err(`<${m[1].toLowerCase()}> loads ${url}, and the canvas has no network egress.`, 'Inline the asset, or draw a marked placeholder instead.');
    }
  }

  // --- Fonts and stylesheets ---------------------------------------------
  for (const m of source.matchAll(/<link\b[^>]*>/g)) {
    const tag = m[0];
    const href = /href\s*=\s*"([^"]*)"/.exec(tag)?.[1] ?? '';
    const sys = /stylesheet/.test(tag) ? systemFile(href) : null;
    if (sys && !sys.ok) systemError('A stylesheet loads', href, sys);
    if (/stylesheet/.test(tag) && !sys && !/^https:\/\/fonts\.googleapis\.com\//.test(href)) {
      err(
        `A stylesheet is loaded from ${href || 'an unquoted href'}, which the canvas blocks.`,
        'Google Fonts is the only permitted host. Inline everything else.',
      );
    }
    if (!allowFonts && /fonts\.googleapis\.com/.test(href)) {
      warn('A web font is loaded, but PNG and PDF export cannot embed it.', 'Pick a fallback with close metrics.');
    }
  }

  // --- House rules -------------------------------------------------------
  const textOnly = source
    .replace(/<!--[\s\S]*?-->/g, '')
    .replace(/<script[\s\S]*?<\/script>/g, '')
    .replace(/<style[\s\S]*?<\/style>/g, '')
    .replace(/<[^>]+>/g, ' ');
  if (EMOJI_RE.test(textOnly)) {
    warn(
      'The artboard contains emoji.',
      'Draw icons as inline SVG on a 16/20/24px grid. Emoji render differently on every platform and read as a tell.',
    );
  }
  // Everything from here to the flex check used to be a third hand-maintained
  // copy of the anti-slop rules, and it disagreed with guardian.mjs: a comment
  // that stood here recorded the day `font-family: 'Inter', sans-serif` passed
  // one validator and failed the other. There is now one implementation, and it
  // reads references/anti-slop.contract.md, which is the document a person edits.
  // Generated sheets are exempt, for the same reason `check` exempts them: the
  // components sheet demonstrates the whole radius scale and the palette sheet
  // numbers twelve ramp steps, so holding either to a rule about restraint is
  // faulting a specimen for containing specimens.
  // Each finding carries its rule, so a caller can tell an anti-slop error
  // (renders fine, reads as machine-made) from a structural one (will not
  // render). They used to print under one heading that said the wrong thing
  // about half of them.
  if (!source.slice(0, 4096).includes(GENERATED_MARKER)) {
    for (const f of slopFindings(loadContractSync(), source, { name, brandFonts })) {
      (f.severity === 'p0' ? errors : warnings).push({ message: f.message, fix: f.fix, rule: f.rule });
    }
  }

  // --- Layout craft ------------------------------------------------------
  // Kept here rather than in the contract because it needs two facts at once,
  // and a regex that spans a whole document to correlate them is a regex that
  // will eventually match something innocent. Sometimes there really are three
  // things and they really are ordered, so it warns rather than fails.
  const threeCol = /grid-template-columns:\s*repeat\(3,\s*minmax\(0,\s*1fr\)\)/.test(source);
  const sequenceNumbering = /(^|>)\s*0?1\s*<[\s\S]{0,600}?(^|>)\s*0?2\s*<[\s\S]{0,600}?(^|>)\s*0?3\s*</m.test(source);
  if (threeCol && sequenceNumbering) {
    warn(
      'A three-column grid numbered 01 / 02 / 03. This is the most-generated section on the internet, and the numbering claims a sequence.',
      'Keep it only if the content genuinely is ordered steps. Otherwise try a single-column editorial run, a comparison, or one full-bleed demonstration.',
    );
  }

  // A page drawn under a dialog's scrim sits in an inert, aria-hidden wrapper, and the detector then reports
  // text-occlusion on every word the scrim covers. The wrapper says so with the detector's own ignore, which is
  // narrow: one rule, on the one subtree covered on purpose (06-canvas.md, a dialog drawn over its page).
  for (const at of inertWithoutIgnore(source)) {
    warn(
      `An inert element (${at}) has no data-impeccable-ignore="text-occlusion" on it or an element around it, in ${name}: the detector will report every word a dialog's scrim covers.`,
      'Put the covered page in one wrapper: <div aria-hidden="true" inert="true" data-impeccable-ignore="text-occlusion" style="position: absolute; inset: 0; overflow: hidden;">.',
    );
  }

  // A MetricCard's context is its delta's comparison and shows only beside one: a run passed context with no delta on
  // four boards, and the line under each figure showed nothing. A generated board shows the kit's own examples, one
  // of which draws exactly that on purpose, to show the context going.
  if (!source.slice(0, 4096).includes(GENERATED_MARKER)) {
    for (const label of contextWithoutDelta(source)) {
      warn(
        `The MetricCard "${label}" in ${name} has a context and no delta, so its context shows nothing: context is the comparison a delta is against.`,
        'Put the line in footnote, which always shows, or give the card the delta its context compares.',
      );
    }
    // LoadingState shows nothing for its first second, so a load that is quick never flashes. A board is drawn in
    // under that second, so one without slow drew a blank frame where a run's loading state should have been.
    for (const title of loadingWithoutSlow(source)) {
      warn(
        `The LoadingState "${title}" in ${name} has no slow, so the board draws nothing where it stands: it shows only after its first second, and a board is drawn before that.`,
        'Give it slow, which draws the long wait as people see it after ten seconds, with how long it usually takes.',
      );
    }
  }

  // A handler or noValidate in a case the canvas may not read. Brandi's shim takes any case, because the HTML parser
  // lowercases names before it sees them, so no preview shows this; only the source does.
  for (const m of miscasedAttributes(source)) {
    err(
      `<${m.tag} ${m.name}> in ${name} is written in a case the Design canvas may not read.`,
      `Write ${m.want}: ${m.tag === 'x-import' || m.tag === 'dc-import' ? 'a prop on a mounted component is kebab-case (on-row-click)' : m.want === 'noValidate' ? 'attributes on an element are JSX (noValidate)' : 'an element\'s handler is JSX camelCase as a whole-value attribute (onClick="{{ item.pick }}")'}.`,
    );
  }

  // A class with no rule in what the board loads does nothing, and nothing says so: the system's bundle holds only
  // the Tailwind classes the kit's own components use, so a board's @min-[900px]:grid-cols-3 fell to one column.
  const unbuilt = stylesheets ? classesWithoutRule(source, stylesheets) : null;
  if (unbuilt?.length) {
    warn(
      `${unbuilt.slice(0, 8).join(', ')}${unbuilt.length > 8 ? ` and ${unbuilt.length - 8} more` : ''} in ${name} ${unbuilt.length === 1 ? 'matches' : 'each match'} no rule in the stylesheets it loads or its own style, so ${unbuilt.length === 1 ? 'it does' : 'they do'} nothing: the system's bundle holds only the Tailwind classes its own components use.`,
      'Write the layout as an inline style or a rule in the board\'s helmet <style> (a media or container query there needs !important to beat an inline style), or use a class the bundle has.',
    );
  }

  // On the canvas a board runs in a frame whose parent is another origin, and reading a property of that parent
  // throws. A script that walks window's properties reads it, so it breaks there and nowhere a preview runs.
  const scripts = [...source.matchAll(/<script\b[^>]*>([\s\S]*?)<\/script>/gi)].map((m) => m[1]).join('\n');
  if (/\bObject\.(values|keys|entries)\(\s*window\s*\)/.test(scripts)) {
    err(
      `A script in ${name} walks window to find something, which throws on the Design canvas: a board's parent frame is another origin.`,
      'Name the bundle outright, window.<Ns>.<Export> (window.Acme.Button); in a component definition\'s logic, write NS.<Export>.',
    );
  }

  const flexCount = (source.match(/display:\s*(flex|grid)/g) ?? []).length;
  const gapCount = (source.match(/\bgap:/g) ?? []).length;
  if (flexCount > 0 && gapCount === 0) {
    warn(
      'Flex or grid containers with no gap.',
      'Space siblings with gap, not margins: gap survives the canvas editor reordering, deleting and duplicating elements.',
    );
  }

  return { name, ok: errors.length === 0, errors, warnings };
}

const VOID_TAGS = new Set(['area', 'base', 'br', 'col', 'embed', 'hr', 'img', 'input', 'link', 'meta', 'source', 'track', 'wbr']);

/**
 * Each inert element in a board's markup with no text-occlusion ignore on it or an element around it, named by
 * its tag and what comes first in its attributes. Scripts and styles are left out, so code that writes markup
 * as text is never read as markup.
 */
export function inertWithoutIgnore(source) {
  const markup = String(source).replace(/<(script|style)\b[^>]*>[\s\S]*?<\/\1>/gi, '');
  const open = [];
  const found = [];
  for (const [, close, tag, attrs] of markup.matchAll(/<(\/?)([a-zA-Z][\w-]*)((?:"[^"]*"|'[^']*'|[^'">])*)>/g)) {
    const t = tag.toLowerCase();
    if (close) {
      const i = open.map((o) => o.tag).lastIndexOf(t);
      if (i >= 0) open.length = i;
      continue;
    }
    const ignores = /\bdata-impeccable-ignore\s*=\s*(["'])[^"']*\btext-occlusion\b[^"']*\1/.test(attrs);
    // Read on the attribute names only, so a title that says "inert" is not an inert element.
    const inert = /(^|\s)inert(\s|=|\/?$)/.test(attrs.replace(/"[^"]*"|'[^']*'/g, '""'));
    if (inert && !ignores && !open.some((o) => o.ignores)) found.push(`<${t}${attrs.trim() ? ` ${attrs.trim().slice(0, 60)}` : ''}>`);
    if (!VOID_TAGS.has(t) && !/\/\s*$/.test(attrs)) open.push({ tag: t, ignores });
  }
  return found;
}

/**
 * The label of each MetricCard mounted with a context and no delta, read from the source: context shows only beside a
 * delta, so on such a card it shows nothing. Scripts, styles and comments are not markup.
 */
/** Each LoadingState on a board with no `slow`, by its title: the board draws a blank where it stands. */
export function loadingWithoutSlow(source) {
  const markup = String(source).replace(/<(script|style)\b[^>]*>[\s\S]*?<\/\1>|<!--[\s\S]*?-->/gi, '');
  const found = [];
  for (const [, attrs] of markup.matchAll(/<(?:x-import|dc-import)\b((?:"[^"]*"|'[^']*'|[^'">])*)>/gi)) {
    const props = new Map([...attrs.matchAll(/([^\s"'=<>/]+)(?:\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s"'>]+)))?/g)].map(([, n, dq, sq, bare]) => [n.toLowerCase(), dq ?? sq ?? bare ?? '']));
    if (!/\.LoadingState$/.test(props.get('component-from-global-scope') ?? '')) continue;
    if (!props.has('slow')) found.push(props.get('title') ?? 'Loading');
  }
  return found;
}

export function contextWithoutDelta(source) {
  const markup = String(source).replace(/<(script|style)\b[^>]*>[\s\S]*?<\/\1>|<!--[\s\S]*?-->/gi, '');
  const found = [];
  for (const [, attrs] of markup.matchAll(/<(?:x-import|dc-import)\b((?:"[^"]*"|'[^']*'|[^'">])*)>/gi)) {
    const props = new Map([...attrs.matchAll(/([^\s"'=<>/]+)(?:\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s"'>]+)))?/g)].map(([, n, dq, sq, bare]) => [n.toLowerCase(), dq ?? sq ?? bare ?? '']));
    if (!/\.MetricCard$/.test(props.get('component-from-global-scope') ?? '')) continue;
    if (props.get('context')?.trim() && !props.has('delta')) found.push(props.get('label') ?? 'with no label');
  }
  return found;
}

// The DOM events whose JSX names are more than a capital letter away from their attribute names.
const JSX_EVENTS = {
  dblclick: 'DoubleClick', keydown: 'KeyDown', keyup: 'KeyUp', keypress: 'KeyPress', mousedown: 'MouseDown', mouseup: 'MouseUp',
  mouseenter: 'MouseEnter', mouseleave: 'MouseLeave', mousemove: 'MouseMove', pointerdown: 'PointerDown', pointerup: 'PointerUp',
  pointerenter: 'PointerEnter', pointerleave: 'PointerLeave', pointermove: 'PointerMove', contextmenu: 'ContextMenu',
  focusin: 'FocusIn', focusout: 'FocusOut', touchstart: 'TouchStart', touchend: 'TouchEnd', touchmove: 'TouchMove',
};

/**
 * Each handler attribute, and each novalidate, written in a case the Design canvas may not read, from the source
 * text: the HTML parser lowercases every name, so the DOM cannot tell onClick from onclick, and Brandi's own shim
 * accepts both. On an element a handler is JSX camelCase (onClick="{{ item.pick }}"); on an x-import or a
 * dc-import, a prop is kebab-case (on-row-click). A handler is a whole {{hole}}: a literal never runs, so a prop
 * that only starts with "on" is left alone. Scripts, styles and comments are not markup.
 */
export function miscasedAttributes(source) {
  const markup = String(source).replace(/<(script|style)\b[^>]*>[\s\S]*?<\/\1>|<!--[\s\S]*?-->/gi, '');
  const found = [];
  for (const [, tag, attrs] of markup.matchAll(/<([a-zA-Z][\w-]*)((?:"[^"]*"|'[^']*'|[^'">])*)>/g)) {
    const t = tag.toLowerCase();
    const mounts = t === 'x-import' || t === 'dc-import';
    for (const [, name, dq, sq, bare] of attrs.matchAll(/([^\s"'=<>/]+)(?:\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s"'>]+)))?/g)) {
      const value = dq ?? sq ?? bare ?? '';
      if (name.toLowerCase() === 'novalidate' && name !== 'noValidate' && !mounts) found.push({ tag: t, name, want: 'noValidate' });
      if (!/^on/i.test(name) || !/^\s*\{\{[^}]*\}\}\s*$/.test(value)) continue;
      // The words of the name, where its case or its hyphens mark them: RowClick, row-click, rowclick.
      const rest = name.slice(2).replace(/^-/, '');
      const words = (/[a-z]/.test(rest) ? rest.replace(/([a-z0-9])([A-Z])/g, '$1-$2') : rest).toLowerCase().split('-').filter(Boolean);
      if (mounts) {
        const want = `on-${words.join('-')}`;
        if (name !== want) found.push({ tag: t, name, want });
      } else if (!/^on[A-Z][A-Za-z]*$/.test(name)) {
        found.push({ tag: t, name, want: `on${JSX_EVENTS[words.join('')] ?? words.map((w) => w.charAt(0).toUpperCase() + w.slice(1)).join('')}` });
      }
    }
  }
  return found;
}

/** The stylesheets a board loads from its own folder, by href, in the order it loads them. Fonts from Google are not its own. */
export function localStylesheets(source) {
  return [...String(source).matchAll(/<link\b[^>]*>/gi)]
    .filter((m) => /\brel\s*=\s*["']?stylesheet/i.test(m[0]))
    .map((m) => /\bhref\s*=\s*"([^"]*)"/i.exec(m[0])?.[1])
    .filter((href) => href && !/^[a-z]+:|^\/\//i.test(href));
}

// CSS.escape, which is what Tailwind escapes a class name with: `md:flex` is written `.md\:flex`.
const cssEscape = (name) => [...name].map((ch, i) => {
  const code = ch.codePointAt(0);
  if ((code >= 1 && code <= 31) || code === 127 || (/\d/.test(ch) && (i === 0 || (i === 1 && name[0] === '-')))) return `\\${code.toString(16)} `;
  if (i === 0 && ch === '-' && name.length === 1) return '\\-';
  return code >= 128 || /[\w-]/.test(ch) ? ch : `\\${ch}`;
}).join('');

/**
 * The classes in a board's markup that no rule in what it loads selects: its own folder's stylesheets
 * (`stylesheets`, href to text, as the caller read them) and its own <style> blocks. Null when the board loads no
 * installed system (`ds/`), or a stylesheet the caller could not read: then nothing can be said. A class from a hole
 * is left alone, and so are scripts and comments.
 */
export function classesWithoutRule(source, stylesheets) {
  const hrefs = localStylesheets(source);
  if (!hrefs.some((h) => /(^|\/)ds\//.test(h)) || hrefs.some((h) => typeof stylesheets?.[h] !== 'string')) return null;
  const css = [...hrefs.map((h) => stylesheets[h]), ...[...String(source).matchAll(/<style\b[^>]*>([\s\S]*?)<\/style>/gi)].map((m) => m[1])].join('\n');
  const markup = String(source).replace(/<(script|style)\b[^>]*>[\s\S]*?<\/\1>|<!--[\s\S]*?-->/gi, '');
  const classes = new Set();
  for (const m of markup.matchAll(/\sclass\s*=\s*(?:"([^"]*)"|'([^']*)')/gi)) {
    for (const c of (m[1] ?? m[2]).replace(/\{\{[^}]*\}\}/g, ' ').split(/\s+/)) if (c && !c.includes('{{') && !c.includes('}}')) classes.add(c);
  }
  // The selector, followed by anything that cannot carry on the name: `.gap` is not `.gap-3`, and `.md` is not `.md\:flex`.
  const selects = (c) => new RegExp(`\\.${cssEscape(c).replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}(?![\\w-]|\\\\)`).test(css);
  return [...classes].filter((c) => !selects(c));
}

/** Validate a whole set at once, plus the manifest that lays them out. */
export function validateCanvas({ artboards, manifest, brandFonts = [], systems = [], stylesheets }) {
  const recorded = [...new Set([...systems, ...(manifest?.designSystems ?? []).map((d) => d.namespace)])];
  const results = artboards.map(({ file, source }) =>
    validateArtboard(source, { name: file, brandFonts, systems: recorded, stylesheets }),
  );
  const errors = results.flatMap((r) => r.errors.map((e) => ({ file: r.name, ...e })));
  const warnings = results.flatMap((r) => r.warnings.map((w) => ({ file: r.name, ...w })));

  // Checked whether or not a manifest exists: the Territories round publishes a
  // freshly written folder with no manifest yet, which is exactly when a missing
  // Main bites, and the old placement inside the manifest branch meant the
  // warning never fired there.
  if (!artboards.some((a) => a.file === 'Main.dc.html')) {
    warnings.push({
      file: 'Main.dc.html',
      message: 'No Main artboard, so the canvas warns and opens on whichever artboard sorts first.',
      fix: 'Name the leading deliverable Main.dc.html so the entry artboard is a decision. During a direction round, Main is the contents page.',
    });
  }

  if (manifest) {
    const files = new Set(artboards.map((a) => a.file));
    for (const b of manifest.artboards) {
      if (!files.has(b.file)) errors.push({ file: b.file, message: 'Listed in canvas.json but not written to disk.', fix: null });
    }
    for (const f of files) {
      if (!manifest.artboards.some((b) => b.file === f)) {
        warnings.push({ file: f, message: 'On disk but not in canvas.json, so it will be appended in an arbitrary slot.', fix: 'Give it a deliberate position.' });
      }
    }
    for (const b of manifest.artboards) {
      for (const k of ['x', 'y', 'w', 'h']) {
        if (typeof b[k] !== 'number' || !Number.isFinite(b[k])) {
          errors.push({ file: b.file, message: `${k} is ${JSON.stringify(b[k])}, which the seeder cannot lay out.`, fix: 'Rebuild the manifest with canvasManifest, which refuses non-finite geometry.' });
        }
      }
      for (const [k, side] of [['w', 'wide'], ['h', 'tall']]) {
        if (Number.isFinite(b[k]) && (b[k] < FRAME_LIMIT.min || b[k] > FRAME_LIMIT.max)) {
          errors.push({ file: b.file, message: `Its frame is ${b[k]}px ${side}; the Design canvas takes ${FRAME_LIMIT.min} to ${FRAME_LIMIT.max}px each way, so it cannot be published.`, fix: 'Split the board into parts that each fit (brandi product boards splits its own), or make it smaller.' });
        }
      }
    }
    for (const clash of findOverlaps(manifest)) {
      errors.push({ file: clash.a, message: `Overlaps ${clash.b}, including the name strip above each frame.`, fix: 'Leave at least 80px between frames in a row and 120px between rows.' });
    }
    for (const tight of findCrowding(manifest)) {
      warnings.push({
        file: tight.a,
        message: `Only ${tight.gap}px from ${tight.b} on the ${tight.axis} axis, where the canvas chrome wants ${tight.min}px.`,
        fix: 'The frames will render, but their titles and tweak chips will crowd each other.',
      });
    }
  }

  return { ok: errors.length === 0, errors, warnings };
}

export default {
  artboard, canvasManifest, validateArtboard, validateCanvas, findOverlaps, findCrowding, FRAME_LIMIT, inertWithoutIgnore, localStylesheets, classesWithoutRule,
  forDesignCanvas, designIndex, encodeProps, decodeProps, FRAMES, BANNED_FONTS, DEFAULT_FONTS,
  systemHeadLines, checkSystemRecord, NAMESPACE_RE,
};
